// Generated by `moqui types` from the loaded definitions. Do not edit.
// The server-static qvt package keys as values, for client code that reads a package or a form-list package.

export const PAGE_SUFFIXES = ["Count", "PageIndex", "PageSize", "PageMaxIndex", "PageRangeLow", "PageRangeHigh"] as const satisfies readonly MoquiPageSuffix[];
export const HEADER_SUFFIXES = ["", "_op", "_not", "_ic", "_from", "_thru", "_poffset", "_period"] as const satisfies readonly MoquiHeaderSuffix[];
export const CREDENTIAL_NAMES = ["password", "oldpassword", "newpassword", "newpasswordverify", "currentpassword", "resetpassword", "authpassword", "api_key", "login_key", "passwordsalt", "passwordhashtype", "passwordbase64", "passwordverify"] as const satisfies readonly MoquiCredentialName[];

/** The keys a form-list `list` loses from the screen package and has in its own package. */
export function pageKeys<L extends string>(list: L): MoquiPageKey<L>[] {
    return PAGE_SUFFIXES.map((suffix) => `${list}${suffix}` as MoquiPageKey<L>);
}

/** Where a form-single's server lookups are kept in the screen package. */
export function extraKey(form: string): `mqExtra_${string}` {
    return `mqExtra_${form}`;
}

/** The key of a drop-down's options: the field's sub-node index among its children, the widget's index in the sub-node. */
export function optionKey(form: string, field: string, subIndex: number, widgetIndex: number): `mqOpt_${string}` {
    return `mqOpt_${form}_${field}_${subIndex}_${widgetIndex}`;
}

/** The props of a server-static qvt screen's template: its package and the browser `ec`. */
export type ScreenProps<S extends keyof MoquiScreenPackages> = MoquiStaticScope<MoquiScreenPackages[S]>;
/** The body of `GET {screen}/actions/{formName}`, by `location#formName`. */
export type FormListProps<F extends keyof MoquiFormListPackages> = MoquiFormListPackages[F];
